message.content:
{
  "gate_token": "dXbKs7scqvV8F-4IGzKYeA",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unfolds a torn map of the ruined royal city.",
      "visual_description": "A windswept hilltop at dusk overlooking a shattered skyline of broken spires; ink-stained hands smooth a creased map weighted with a brass compass.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of a trap inside the gates.",
      "visual_description": "A small campfire throws long shadows; an oil lamp tilts forward, its single flame-eye glowing wide as Mara listens.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox returns with a scrap of royal banner.",
      "visual_description": "A clockwork fox trots across cracked cobblestones, key-wind tail ticking, a strip of faded crimson cloth clenched in its jaw.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "They approach the great castle gates at moonrise.",
      "visual_description": "Twin iron gates loom under a pale moon, carved with worn lions; Mara crouches behind rubble while the tin fox sniffs the threshold.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The glass diver slips out from a cracked window.",
      "visual_description": "A figure in a clear diving helmet emerges shimmering from a shattered pane, coat reflecting broken city lights like fish scales.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "Townsfolk peer in fear from shuttered windows.",
      "visual_description": "Narrow alley lined with leaning houses; pale faces glimmer behind slatted shutters as the tin fox pads silently past.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "An armored patrol clatters past their hiding place.",
      "visual_description": "From inside a dark doorway, lantern light flares on passing helmets and pikes; Mara presses a finger to her lips while the oracle lamp dims itself.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "They find the sleeping tax collector blocking a stair.",
      "visual_description": "A plump official snores upright on a stone step, ledger book under his cheek, stamped papers fluttering from his sleeves.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The cursed tower whispers rumors of a sleeping beast.",
      "visual_description": "A leaning black tower wreathed in green mist; carved scales coil along its base while the oracle lamp flickers nervously in Mara's hand.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "The glass diver dives into a tower mirror.",
      "visual_description": "A tall silver mirror ripples like water; the diver plunges in headfirst, coat trailing reflections of distant flames.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Inside the mirror world, the diver finds the captive.",
      "visual_description": "A hall of floating glass shards; in the center, the sleeping tax collector slumps chained to a chair, ledger still clutched tight.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "The tin fox picks the lock of a magic door.",
      "visual_description": "An arched door inlaid with shifting runes; the clockwork fox inserts its tail-key, gears whirring as glyphs spin into alignment.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "Old royal banners ignite as an alarm spell triggers.",
      "visual_description": "Tattered banners along a stone corridor burst into blue flame, casting Mara and the oracle lamp into stark silhouette.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "The oracle lamp shouts the safe path through smoke.",
      "visual_description": "Thick smoke curls down a collapsing hallway; the lamp's flame-eye stretches into an arrow pointing left as Mara runs.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "The glass diver hauls the sleeper out of a puddle.",
      "visual_description": "A rain puddle in a courtyard ripples wide; the diver pulls the sleeping tax collector upward through it like surfacing from a pond.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "Reunited, the team sprints for the river bridge.",
      "visual_description": "A long stone bridge stretches over a black river under a red dawn; four figures dash across worn flagstones, tin fox in the lead.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The tin fox collapses a bridge span behind them.",
      "visual_description": "Sparks fly as the fox bites a rune-carved keystone; stones tumble into churning water, cutting off pursuing torchlight.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, Mara marks the city as fallen.",
      "visual_description": "On a misty riverbank at sunrise, Mara inks a heavy X across the city on her map while the oracle lamp glows softly and the fox curls at her feet.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver", "sleeping_tax_collector"]
    }
  ]
}

